/*
 * A386982  Values of w in the quartets (2, u, v, w) of type 2; i.e., values
 *          of v for solutions to 2(2 + u) = v(v - w), in distinct positive
 *          integers, with v > 1, sorted by nondecreasing values of u; see
 *          A385884.
 * https://oeis.org/A386982
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = w where (2,u,v,w) are distinct positive integers
 *            satisfying * 2(2 + u) = v(v - w). The terms are generated by
 *            enumerating u in * increasing order (skipping u = 2) and
 *            collecting all valid w, * sorted ascending within each u
 * Range:     u8 n <= 71, u16 n <= 71, u32 n <= 71, u64 n <= 71, u128 n <= 71,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

/* Helper: insertion sort for small arrays of seq_t */
static void sort_seq_t(seq_t *arr, int len)
{
    for (int i = 1; i < len; ++i) {
        seq_t key = arr[i];
        int j = i - 1;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            --j;
        }
        arr[j + 1] = key;
    }
}

seq_t a(idx_t n)
{
    if (n == 0) return 0; /* offset 1, but handle gracefully */

    size_t count = 0;          /* number of terms generated so far */
    seq_t w_val = 0;           /* placeholder for returned value */

    for (idx_t u = 1; ; ++u) {
        if (u == 2) continue; /* 2 must be distinct from u */

        /* f = 2(u+2) as idx_t; fits for all practical n */
        idx_t f_int = 2 * u + 4;
        /* array for w values found for this u */
        seq_t local[128];
        int len = 0;

        /* iterate divisors t of f */
        for (idx_t t = 1; t * t <= f_int; ++t) {
            if (f_int % t != 0) continue;
            idx_t v_int = f_int / t;
            if (t == v_int) continue;           /* v == t -> w = 0 */
            seq_t v = (seq_t)v_int;
            seq_t w = v - (seq_t)t;
            if (w <= (seq_t)0) continue;        /* should not happen */

            /* distinctness checks */
            if ((seq_t)2 == w) continue;
            if ((seq_t)2 == v) continue;        /* v = 2 is impossible but guard */
            if ((seq_t)u == v) continue;
            if ((seq_t)u == w) continue;
            if (v == w) continue;

            /* store valid w */
            if (len < 128) local[len++] = w;
        }

        /* sort w values for this u */
        sort_seq_t(local, len);

        /* accumulate in global order */
        for (int i = 0; i < len; ++i) {
            ++count;
            if (count == n) {
                w_val = local[i];
                return w_val;
            }
        }
    }
}
